/**
 * Camp themes ("structure packs"): the single point through which core code
 * reads camp customization (Phase 2.5, made per camp in
 * `plans/hosting-other-camps.md`).
 *
 * A pack is a workspace package exporting a `CampTheme`. Which packs a build
 * bundles is decided at build time (`app/theme/packs.ts`, generated by Vite):
 *
 * - `CAMP_THEME` names packs that are **server-wide**: every camp gets them.
 *   This is how a single-camp deployment (Math Camp's) has always worked.
 * - `CAMP_THEMES` names packs a super admin can switch on **per camp**, for a
 *   shared deployment hosting several camps.
 *
 * Every bundled structure joins one registry (`campStructures`), so any saved
 * object always renders. What a camp may *place* is narrower: the structures of
 * per-camp packs it hasn't been given are hidden and refused, through the same
 * path as an edition's banned kinds (see `unavailableKinds`).
 */
import type { CampStructure } from "@camptool/theme-contract";
import type { ThemePack } from "./pack-types";
import { PACKS } from "./packs";

/** Build the registry views over a set of bundled packs. Pure, so tests can
 * hand it any packs without mocking the generated module. */
export function packRegistry(all: readonly ThemePack[]) {
  const seen = new Map<string, string>();
  const structures: CampStructure[] = [];
  for (const p of all) {
    for (const s of p.theme.structures) {
      const other = seen.get(s.value);
      if (other) {
        throw new Error(
          `Structure kind "${s.value}" is defined by both ${other} and ${p.key}; kind values must be unique across camp-theme packs.`,
        );
      }
      seen.set(s.value, p.key);
      structures.push(s);
    }
  }
  return {
    /** Every structure from every bundled pack. */
    structures: structures as readonly CampStructure[],
    /** Packs a super admin can switch on per camp. */
    perCamp: all
      .filter((p) => !p.global)
      .map((p) => ({ key: p.key, name: p.theme.name ?? p.key })),
    /** Kinds a camp may not place: those of per-camp packs it hasn't been
     * given. Takes the camp's stored `structure_packs` value. */
    unavailableKinds(raw: string | null | undefined): string[] {
      const enabled = new Set(parseStructurePacks(raw));
      return all
        .filter((p) => !p.global && !enabled.has(p.key))
        .flatMap((p) => p.theme.structures.map((s) => s.value));
    },
  };
}

const registry = packRegistry(PACKS);

/** Every structure from every bundled pack. Kind values are unique. */
export const campStructures: readonly CampStructure[] = registry.structures;

/** Packs a super admin can switch on per camp (the non-server-wide ones). */
export const perCampPacks: readonly { key: string; name: string }[] =
  registry.perCamp;

/** Structure kinds this camp may not place (see `packRegistry`). */
export const unavailableKinds = registry.unavailableKinds;

/** Parse a camp's stored pack list (`camp.structure_packs`, a JSON array of
 * package names). NULL or garbage means none. */
export function parseStructurePacks(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const v = JSON.parse(raw);
    return Array.isArray(v)
      ? v.filter((x): x is string => typeof x === "string")
      : [];
  } catch {
    return [];
  }
}

/** Serialize a camp's pack list for storage (deduped, stable). */
export function serializeStructurePacks(keys: Iterable<string>): string {
  return JSON.stringify([...new Set(keys)].sort());
}

export type { CampStructure, CampTheme } from "@camptool/theme-contract";
